2	import { runInNewContext } from "node:vm";
3	import { H3, HTTPError, type H3Event } from "../src/index.ts";
4	import { describeMatrix } from "./_setup.ts";
5	
6	describeMatrix("errors", (t, { it, expect, describe }) => {
7	  const consoleMock = ((globalThis.console.error as any) = vi.fn());
8	
9	  describe("error response bodies", () => {
10	    for (const withOnError of [false, true]) {
11	      const hook = withOnError ? "with onError" : "without onError";
12	
13	      it(`omits the body for a missing HEAD route ${hook}`, async () => {
14	        if (!withOnError) t.app.config.onError = undefined;
15	        const res = await t.fetch("/missing", { method: "HEAD" });
16	        expect(res.status).toBe(404);
17	        // A HEAD body is not rendered, so no (mismatching) content-length is advertised
18	        expect(res.headers.get("content-length")).toBeNull();
19	        expect(await res.text()).toBe("");
20	        expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
21	        expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
22	      });
23	
24	      for (const asyncHandler of [false, true]) {
25	        for (const method of ["GET", "HEAD"]) {
26	          it(`renders ${method} errors from a ${asyncHandler ? "async" : "sync"} handler ${hook}`, async () => {
27	            if (!withOnError) t.app.config.onError = undefined;
28	            const handler = (event: H3Event) => {
29	              event.res.headers.set("x-success", "success");
30	              event.res.errHeaders.set("x-error", "prepared");
31	              event.res.errHeaders.append("set-cookie", "prepared=1");
32	              throw new HTTPError({
33	                status: 422,
34	                statusText: "Unprocessable",
35	                data: { test: 123 },
36	                headers: { "x-error-own": "own", "set-cookie": "error=1" },
37	              });
38	            };
39	            t.app.use(asyncHandler ? async (event) => handler(event) : handler);
40	
41	            const res = await t.fetch("/", { method });
42	            expect(res.status).toBe(422);
43	            expect(res.statusText).toBe("Unprocessable");
44	            expect(res.headers.get("content-type")).toBe("application/json;charset=UTF-8");
45	            expect(res.headers.get("x-error")).toBe("prepared");
46	            expect(res.headers.get("x-error-own")).toBe("own");
47	            expect(res.headers.get("x-success")).toBeNull();
48	            expect(res.headers.getSetCookie()).toEqual(["error=1", "prepared=1"]);
49	            if (method === "HEAD") {
50	              expect(res.headers.get("content-length")).toBeNull();
51	              expect(await res.text()).toBe("");
52	            } else {
53	              expect(await res.json()).toMatchObject({
54	                status: 422,
55	                statusText: "Unprocessable",
56	                data: { test: 123 },
57	              });
58	            }
59	            expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
60	            expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
61	          });
62	        }
63	      }
64	    }
65	  });
66	
67	  it("throw HTTPError", async () => {
68	    t.app.use(() => {
69	      throw new HTTPError({
70	        statusText: "Unprocessable",
71	        status: 422,
72	        data: { test: 123 },
73	        body: { topLevel: "works" },
74	      });
75	    });
76	    const result = await t.fetch("/");
77	    expect(result.status).toBe(422);
78	    expect(result.statusText).toBe("Unprocessable");
79	    expect(await result.json()).toMatchObject({
80	      status: 422,
81	      statusText: "Unprocessable",
82	      message: "Unprocessable",
83	      data: { test: 123 },
84	      topLevel: "works",
85	    });
86	  });
87	
88	  it("return HTTPError", async () => {
89	    t.app.use(() => {
90	      return new HTTPError({
91	        statusText: "Unprocessable",
92	        status: 422,
93	        data: { test: 123 },
94	      });
95	    });
96	    const result = await t.fetch("/");
97	    expect(result.status).toBe(422);
98	    expect(result.statusText).toBe("Unprocessable");
99	    expect(await result.json()).toMatchObject({
100	      status: 422,
101	      statusText: "Unprocessable",
102	      message: "Unprocessable",
103	      data: { test: 123 },
104	    });
105	  });
106	
107	  it("unandled errors", async () => {
108	    t.app.use("/api/test", () => {
109	      // @ts-expect-error
110	      foo.bar = 123;
111	    });
112	    const result = await t.fetch("/api/test");
113	
114	    expect(t.errors[0].message).toMatch("foo is not defined");
115	    expect(t.errors[0].unhandled).toBe(true);
116	    t.errors = [];
117	
118	    expect(result.status).toBe(500);
119	    expect(JSON.parse(await result.text())).toMatchObject({
120	      status: 500,
121	    });
122	  });
123	
124	  it("can send runtime error", async () => {
125	    consoleMock.mockReset();
126	
127	    t.app.get("/api/test", () => {
128	      throw new HTTPError({
129	        status: 400,
130	        statusText: "Bad Request",
131	        data: {
132	          message: "Invalid Input",
133	        },
134	      });
135	    });
136	
137	    const result = await t.fetch("/api/test");
138	
139	    expect(result.status).toBe(400);
140	    expect(result.headers.get("content-type")).toMatch("application/json");
141	
142	    expect(console.error).not.toBeCalled();
143	
144	    expect(JSON.parse(await result.text())).toMatchObject({
145	      status: 400,
146	      statusText: "Bad Request",
147	      data: {
148	        message: "Invalid Input",
149	      },
150	    });
151	  });
152	
153	  it("can access original error", async () => {
154	    class CustomError extends Error {
155	      customError = true;
156	    }
157	
158	    t.app.get("/", () => {
159	      throw new HTTPError(new CustomError());
160	    });
161	
162	    const res = await t.fetch("/");
163	    expect(res.status).toBe(500);
164	
165	    expect(t.errors[0].cause).toBeInstanceOf(CustomError);
166	  });
167	
168	  it("can inherit from cause", async () => {
169	    class CustomError extends Error {
170	      override cause = new HTTPError({
171	        status: 400,
172	        statusText: "Bad Request",
173	        unhandled: true,
174	      });
175	    }
176	
177	    t.app.get("/", () => {
178	      throw new HTTPError(new CustomError());
179	    });
180	
181	    const res = await t.fetch("/");
182	    expect(res.status).toBe(400);
183	    expect(t.errors[0].unhandled).toBe(true);
184	
185	    t.errors = [];
186	  });
187	
188	  it("can inherit deprecated statusCode/statusMessage from cause", async () => {
189	    const cause = { statusCode: 404, statusMessage: "Not Found" };
190	
191	    t.app.get("/", () => {
192	      throw new HTTPError({ cause });
193	    });
194	
195	    const res = await t.fetch("/");
196	    expect(res.status).toBe(404);
197	    expect(res.statusText).toBe("Not Found");
198	
199	    t.errors = [];
200	  });
201	
202	  it("error headers", async () => {
203	    t.app.config.onError = async (error, event) => {
204	      const headers = new Headers(event.res.headers);
205	      headers.set("set-cookie", "error=1");
206	      return new Response(error.toString(), { status: 501, headers });
207	    };
208	
209	    t.app.get("/", async (event) => {
210	      event.res.headers.set("set-cookie", "auth=1");
211	      event.res.headers.set("x-test", "1");
212	      throw new HTTPError("test");
213	    });
214	
215	    const res = await t.fetch("/");
216	    expect(res.status).toBe(501);
217	    expect(res.headers.get("x-test")).toBe("1");
218	    expect(res.headers.getSetCookie()).toEqual(["error=1"]);
219	
220	    t.errors = [];
221	  });
222	
223	  it("throw number coerces to status", async () => {
224	    t.app.use(() => {
225	      throw 404;
226	    });
227	    const res = await t.fetch("/");
228	    expect(res.status).toBe(404);
229	  });
230	
231	  it("throw async number coerces to status", async () => {
232	    t.app.use(async () => {
233	      throw 500;
234	    });
235	    const res = await t.fetch("/");
236	    expect(res.status).toBe(500);
237	  });
238	
239	  it("return number is unchanged", async () => {
240	    t.app.use(() => 404);
241	    const res = await t.fetch("/");
242	    expect(res.status).toBe(200);
243	    expect(await res.json()).toBe(404);
244	  });
245	
246	  describe("non-Error throws", () => {
247	    it("throw object does not leak into the response body", async () => {
248	      t.app.use(() => {
249	        throw { secret: "db-password", message: "internal detail", status: 403 };
250	      });
251	      const res = await t.fetch("/");
252	      // A non-Error object is always an unhandled 500; nothing on it shapes the response
253	      expect(res.status).toBe(500);
254	      const body = await res.text();
255	      expect(body).not.toContain("db-password");
256	      expect(body).not.toContain("internal detail");
257	      expect(JSON.parse(body)).toMatchObject({ status: 500, unhandled: true });
258	
259	      expect(t.errors[0].unhandled).toBe(true);
260	      expect(t.errors[0].cause).toMatchObject({ secret: "db-password" });
261	      t.errors = [];
262	    });
263	
264	    // A non-Error object is never trusted to shape the response, not even via a `status` shorthand
265	    // (unlike `throw 404`). `status` / `statusCode` / `statusText` / `headers` are all dropped.
266	    it("status on a thrown object is never honored", async () => {
267	      const shapes = [
268	        { status: 403 },
269	        { statusCode: 429 },
270	        { status: 400, statusText: "Leaky Status Text" },
271	      ];
272	      for (const [i, shape] of shapes.entries()) {
273	        t.app.get(`/shape-${i}`, () => {
274	          throw shape;
275	        });
276	        const res = await t.fetch(`/shape-${i}`);
277	        expect(res.status).toBe(500);
278	        expect(res.statusText).not.toBe("Leaky Status Text");
279	      }
280	      t.errors = [];
281	    });
282	
283	    it("throw async object does not leak into the response body", async () => {
284	      t.app.use(async () => {
285	        throw { secret: "db-password" };
286	      });
287	      const res = await t.fetch("/");
288	      expect(res.status).toBe(500);
289	      expect(await res.text()).not.toContain("db-password");
290	      t.errors = [];
291	    });
292	
293	    it("throw string", async () => {
294	      t.app.use(() => {
295	        throw "not-an-error";
296	      });
297	      const res = await t.fetch("/");
298	      expect(res.status).toBe(500);
299	      expect(await res.text()).not.toContain("not-an-error");
300	      t.errors = [];
301	    });
302	
303	    it("throw undefined", async () => {
304	      t.app.use(() => {
305	        throw undefined;
306	      });
307	      const res = await t.fetch("/");
308	      expect(res.status).toBe(500);
309	      expect(await res.json()).toMatchObject({ status: 500, unhandled: true });
310	      t.errors = [];
311	    });
312	
313	    it("thrown object cannot forge response headers", async () => {
314	      t.app.use(() => {
315	        throw { headers: { "x-forged": "1" } };
316	      });
317	      const res = await t.fetch("/");
318	      expect(res.status).toBe(500);
319	      expect(res.headers.get("x-forged")).toBe(null);
320	      t.errors = [];
321	    });
322	
323	    // `toError` must use the same `instanceof Error` check as `prepareResponse`. A broader check
324	    // (e.g. `Error.isError`) would pass this through, only for `prepareResponse` to reject it and
325	    // render it as a successful body again.
326	    it("cross-realm error is not rendered as a body", async () => {
327	      const foreign = runInNewContext(`new Error("cross-realm secret")`);
328	      t.app.use(() => {
329	        throw foreign;
330	      });
331	      const res = await t.fetch("/");
332	      expect(res.status).toBe(500);
333	      expect(await res.text()).not.toContain("cross-realm secret");
334	      t.errors = [];
335	    });
336	
337	    // Fetch clients (ky, got) throw their own errors named `HTTPError`, without `status`, whose
338	    // message carries the upstream request URL. They must not pass as h3 `HTTPError`s.
339	    it("foreign error named HTTPError without status is unhandled", async () => {
340	      class UpstreamHTTPError extends Error {
341	        override name = "HTTPError";
342	      }
343	      const foreign = new UpstreamHTTPError("Request failed: GET https://internal/?token=secret");
344	      expect(HTTPError.isError(foreign)).toBe(false);
345	      t.app.use(() => {
346	        throw foreign;
347	      });
348	      const res = await t.fetch("/");
349	      expect(res.status).toBe(500);
350	      expect(await res.json()).toMatchObject({ unhandled: true, message: "HTTPError" });
351	      expect(t.errors[0].unhandled).toBe(true);
352	      t.errors = [];
353	    });
354	
355	    it("onError receives the wrapped error", async () => {
356	      const onError = vi.fn();
357	      const app = new H3({ onError, silent: true });
358	      app.use(() => {
359	        throw { secret: "db-password" };
360	      });
361	      const res = await app.request("/");
362	      expect(res.status).toBe(500);
363	      expect(onError).toHaveBeenCalledTimes(1);
364	      const error = onError.mock.calls[0][0];
365	      expect(HTTPError.isError(error)).toBe(true);
366	      expect(error.unhandled).toBe(true);
367	      expect(error.cause).toMatchObject({ secret: "db-password" });
368	    });
369	  });
370	
371	  // Regression for #1477: a synchronous throw while preparing the response (circular
372	  // `JSON.stringify`) must be routed through the same 500 pipeline as any other error,
373	  // not escape `fetch()` as a raw exception/rejection.
374	  describe("response preparation throws", () => {
375	    it("circular return value is rendered as a 500 instead of escaping fetch()", async () => {
376	      t.app.use(() => {
377	        const circular: any = {};
378	        circular.self = circular;
379	        return circular;
380	      });
381	
382	      const res = await t.fetch("/");
383	      expect(res.status).toBe(500);
384	      expect(await res.json()).toMatchObject({ status: 500, unhandled: true });
385	      t.errors = [];
386	    });
387	
388	    it("thrown HTTPError with circular data is rendered as a 500 instead of escaping fetch() (no onError)", async () => {
389	      // With no `onError` configured, `errorResponse()`'s `JSON.stringify` runs
390	      // synchronously in the same pass as the throw (the async/onError branch is not
391	      // taken), so this exercises the raw synchronous-escape path directly.
392	      t.app.config.onError = undefined;
393	      t.app.use(() => {
394	        const data: any = {};
395	        data.self = data;
396	        throw new HTTPError({ status: 400, data });
397	      });
398	
399	      const res = await t.fetch("/");
400	      expect(res.status).toBe(500);
401	    });
402	  });
403	
404	  // Regression for #1503 (CodeRabbit): a synchronously-throwing `onError` hook must not
405	  // recurse infinitely. `Promise.resolve(onError(error, event))` evaluates the call before
406	  // wrapping it in a promise, so a sync throw there escaped `prepareResponse()` synchronously.
407	  // That was caught by `toResponse()`'s try/catch (added for #1477) and re-entered
408	  // `toResponse` with `nested` reset to `false` — calling the same throwing `onError` again,
409	  // forever (stack overflow instead of a normalized 500).
410	  it("a synchronously-throwing onError does not recurse infinitely", async () => {
411	    t.app.config.onError = () => {
412	      throw new Error("onError boom");
413	    };
414	    t.app.use(() => {
415	      throw new Error("handler boom");
416	    });
417	
418	    const res = await t.fetch("/");
419	    expect(res.status).toBe(500);
420	    expect(await res.json()).toMatchObject({ status: 500, unhandled: true });
421	  });
422	
423	  // A value returned from `onError` replaces the response, so a value *thrown* by the hook must be
424	  // normalized through `toError()` first. Otherwise the two are indistinguishable and a non-Error
425	  // throw is rendered as a successful body: the hook's internals leak to the client and the failed
426	  // request reports 200.
427	  for (const [label, thrown] of [
428	    ["an object", { secret: "s3cr3t" }],
429	    ["a string", "leaked internal string"],
430	  ] as const) {
431	    it(`an onError throwing ${label} renders an unhandled 500, not a 200 body`, async () => {
432	      t.app.config.onError = () => {
433	        throw thrown;
434	      };
435	      t.app.use(() => {
436	        throw new Error("handler boom");
437	      });
438	
439	      const res = await t.fetch("/");
440	      expect(res.status).toBe(500);
441	      const body = await res.json();
