      // taken), so this exercises the raw synchronous-escape path directly.
      t.app.config.onError = undefined;
      t.app.use(() => {
        const data: any = {};
        data.self = data;
        throw new HTTPError({ status: 400, data });
      });

      const res = await t.fetch("/");
