        expect(new HTTPError({ status: 404, message: "m" }).toJSON()).toEqual({
          type: "about:blank",
          title: "Not Found",
          status: 404,
          detail: "m",
          message: "m",
          statusText: undefined,
          unhandled: undefined,
          data: undefined,
          instance: undefined,
        });
      });
    });

