      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      const body = await res.json();
      expect(body).toMatchObject({ status: 500, unhandled: true });
      expect(JSON.stringify(body)).not.toContain("s3cr3t");
      expect(JSON.stringify(body)).not.toContain("leaked internal string");
    });
  }

  it("an onError throwing a number renders that status", async () => {
    t.app.config.onError = () => {
      throw 418;
    };
    t.app.use(() => {
      throw new Error("handler boom");
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(418);
  });

  describe("problem details (RFC 9457)", () => {
    const problemType = "application/problem+json";

    describe("content-type", () => {
      it("thrown HTTPError", async () => {
        t.app.use(() => {
          throw new HTTPError({ status: 400 });
        });
        const res = await t.fetch("/");
        expect(res.status).toBe(400);
        expect(res.headers.get("content-type")).toMatch(new RegExp(`^${problemType}`));
      });

      it("missing route", async () => {
        const res = await t.fetch("/missing");
        expect(res.status).toBe(404);
        expect(res.headers.get("content-type")).toBe(problemType);
      });

      it("thrown number", async () => {
        t.app.use(() => {
          throw 404;
        });
        const res = await t.fetch("/");
        expect(res.status).toBe(404);
        expect(res.headers.get("content-type")).toBe(problemType);
      });

      it("unknown error", async () => {
        t.app.use(() => {
          throw new Error("boom");
        });
        const res = await t.fetch("/");
        expect(res.status).toBe(500);
        expect(res.headers.get("content-type")).toBe(problemType);
        t.errors = [];
      });

      it("error thrown in middleware", async () => {
        t.app.use(() => {
          throw new HTTPError({ status: 403 });
        });
        t.app.get("/", () => "ok");
        const res = await t.fetch("/");
        expect(res.status).toBe(403);
        expect(res.headers.get("content-type")).toBe(problemType);
      });

      it("non error responses keep application/json", async () => {
        t.app.use(() => ({ ok: true }));
        const res = await t.fetch("/");
        expect(res.headers.get("content-type")).toBe("application/json;charset=UTF-8");
      });
    });

    describe("members", () => {
      it("default members", async () => {
        t.app.use(() => {
          throw new HTTPError({ status: 404, message: "Usuário não existe" });
        });
        const body = await (await t.fetch("/")).json();
        expect(body).toMatchObject({
          type: "about:blank",
          title: "Not Found",
          status: 404,
          detail: "Usuário não existe",
        });
        expect(body).not.toHaveProperty("instance");
      });

      it("title from statusText or fallback", async () => {
        t.app.get("/custom", () => {
          throw new HTTPError({ status: 422, statusText: "Unprocessable" });
        });
        t.app.get("/unknown", () => {
          throw new HTTPError({ status: 599 });
        });
        expect((await (await t.fetch("/custom")).json()).title).toBe("Unprocessable");
        expect((await (await t.fetch("/unknown")).json()).title).toBe("HTTPError");
