      });

      it("toJSON returns the problem format", () => {
        expect(new HTTPError({ status: 404, message: "m" }).toJSON()).toEqual({
          type: "about:blank",
          title: "Not Found",
          status: 404,
          detail: "m",
          message: "m",
          statusText: undefined,
          unhandled: undefined,
          data: undefined,
          instance: undefined,
        });
      });
    });

    describe("unhandled errors", () => {
      it("do not leak", async () => {
        t.app.use(() => {
          throw new Error("segredo interno");
        });
        const res = await t.fetch("/");
        const text = await res.text();
        expect(res.status).toBe(500);
        expect(text).not.toContain("segredo interno");
        const body = JSON.parse(text);
        expect(body).toMatchObject({
          type: "about:blank",
          title: "Internal Server Error",
          status: 500,
        });
        expect(body).not.toHaveProperty("detail");
        expect(body).not.toHaveProperty("stack");
        t.errors = [];
      });

      it("ignore type and instance", () => {
        const json = new HTTPError({
          status: 400,
          unhandled: true,
          type: "https://x.test/t",
          instance: "/i",
        }).toJSON();
        expect(json.type).toBe("about:blank");
        expect(json.instance).toBeUndefined();
        expect(json.detail).toBeUndefined();
      });

      it("include stack in debug mode", async () => {
        t.app.config.debug = true;
        t.app.use(() => {
          throw new Error("boom");
        });
        const body = await (await t.fetch("/")).json();
        expect(body.stack).toBeInstanceOf(Array);
        t.errors = [];
      });
    });

    describe("headers", () => {
      it("preserves error headers and status", async () => {
        t.app.use(() => {
          throw new HTTPError({ status: 401, headers: { "www-authenticate": "Basic" } });
        });
        const res = await t.fetch("/");
        expect(res.status).toBe(401);
        expect(res.headers.get("www-authenticate")).toBe("Basic");
        expect(res.headers.get("content-type")).toBe(problemType);
      });

      it("custom content-type prevails", async () => {
        t.app.use(() => {
          throw new HTTPError({ status: 400, headers: { "content-type": "application/json" } });
        });
        const res = await t.fetch("/");
        expect(res.headers.get("content-type")).toBe("application/json");
      });

      it("keeps HTTP statusText", async () => {
        t.app.use(() => {
          throw new HTTPError({ status: 422, statusText: "Unprocessable" });
        });
        const res = await t.fetch("/");
        expect(res.statusText).toBe("Unprocessable");
      });
    });
  });
});

